(async () => {
  await connectDB();
  if (await Test.findOne({ testName: NAME })) { console.log(`"${NAME}" already exists - nothing changed.`); return process.exit(0); }
  const date = process.env.MOCK_DATE || addDays(today(), 1);
  const test = await Test.create({ testName: NAME, description: "Placement mock test 2: basic to intermediate. Reasoning Ability: 15, Technical Ability (Quant): 10, Verbal: 20, Pseudo Code: 5, Numerical Puzzle: 4, English Grammar Test: 5, English Written Test: 1.", scheduledDate: date, sections, isActive: false, isSeeded: true, seedKey: 'mock2' });
  for (const s of sections) {
    const list = questions[s.key] || [];
    if (list.length !== s.questionCount) throw new Error(`${s.sectionName}: expected ${s.questionCount} questions, found ${list.length}`);
    await Question.insertMany(list.map((q, i) => {
      if (s.type === 'objective' && (!Array.isArray(q.options) || q.options.length !== 4 || !Number.isInteger(q.answer) || q.answer < 0 || q.answer > 3)) throw new Error('Bad question: ' + q.text.slice(0, 60));
      return {
        testId: test._id, section: s.key, order: i + 1, text: q.text, difficulty: q.difficulty, topic: q.topic, explanation: q.explanation,
        questionType: s.type, options: s.type === 'objective' ? q.options : [],
        correctOption: s.type === 'objective' ? q.answer : undefined,
        marks: s.type === 'objective' ? s.marksPerQuestion : 0, isSeeded: true, seedKey: 'mock2:' + s.key + ':' + (i + 1)
      };
    }));
  }
  if (process.env.MOCK_ACTIVE !== '0') { test.isActive = true; await test.save(); }   // only after every section has its questions
  console.log(`Created "${NAME}" for ${test.scheduledDate}: ${test.totalDuration} min, ${test.totalMarks} marks, ${test.isActive ? 'active' : 'draft'}.`);
  process.exit(0);
})().catch(e => { console.error(e.message); process.exit(1); });
